'use strict';

// MODULES //

var constantFunction = require( '@stdlib/utils-constant-function' );
var isnan = require( '@stdlib/math-base-assert-is-nan' );
var sin = require( '@stdlib/math-base-special-sin' );
var abs2 = require( '@stdlib/math-base-special-abs2' );
var PI = require( '@stdlib/constants-float64-pi' );


// VARIABLES //

var PI_OVER_4 = PI / 4.0;


// MAIN //

/**
* Returns a function for evaluating the cumulative distribution function (CDF) for an anglit distribution with location parameter `mu` and scale parameter `sigma` at a value `x`.
*
* @param {number} mu - location parameter
* @param {PositiveNumber} sigma - scale parameter
* @returns {Function} CDF
*
* @example
* var cdf = factory( 0.0, 1.0 );
* var y = cdf( 0.0 );
* // returns 0.5
*
* y = cdf( 2.0 );
* // returns 1.0
*/
function factory( mu, sigma ) {
	if (
		isnan( mu ) ||
		isnan( sigma ) ||
		sigma <= 0.0
	) {
		return constantFunction( NaN );
	}
	return cdf;

	/**
	* Evaluates the cumulative distribution function (CDF) for an anglit distribution.
	*
	* @private
	* @param {number} x - input value
	* @returns {Probability} evaluated CDF
	*
	* @example
	* var y = cdf( 2.0 );
	* // returns <number>
	*/
	function cdf( x ) {
		var y;

		if ( isnan( x ) ) {
			return NaN;
		}

		// Transform x to the standardized form
		y = ( x - mu ) / sigma;
		if ( y <= -PI_OVER_4 ) {
			return 0.0;
		}
		if ( y >= PI_OVER_4 ) {
			return 1.0;
		}
		return abs2( sin( y + PI_OVER_4 ) );
	}
}


// EXPORTS //

module.exports = factory;
